#include <assert.h>
#include "../kernel/resource_core.h"
int main(void){struct hw_resource_map m;hw_resource_map_init(&m);assert(hw_resource_reserve(&m,0x1000,0x1000,HW_RESOURCE_MMIO,1)==0);assert(hw_resource_contains(&m,0x1800,0x100,HW_RESOURCE_MMIO));assert(!hw_resource_contains(&m,0x1f00,0x200,HW_RESOURCE_MMIO));assert(hw_resource_claim(&m,0x1800,0x100,HW_RESOURCE_MMIO,2)==-2);assert(hw_resource_claim(&m,0x3000,0x1000,HW_RESOURCE_MMIO,2)==0);assert(hw_resource_claim(&m,0x3800,0x100,HW_RESOURCE_MMIO,3)==-2);assert(hw_resource_release(&m,0x3000,0x1000,HW_RESOURCE_MMIO,2)==0);assert(hw_resource_release(&m,0x1000,0x1000,HW_RESOURCE_MMIO,1)==-1);assert(hw_resource_claim(&m,~0ULL,2,HW_RESOURCE_IOPORT,9)==-1);struct hw_resource_map full;hw_resource_map_init(&full);for(uint32_t i=0;i<HW_RESOURCE_CAPACITY;i++)assert(hw_resource_claim(&full,0x10000U+(uint64_t)i*0x1000U,0x100,HW_RESOURCE_MMIO,i+1)==0);assert(full.count==HW_RESOURCE_CAPACITY);assert(hw_resource_claim(&full,0x900000,0x100,HW_RESOURCE_MMIO,500)==-3);assert(hw_resource_release(&full,0x10000U+10U*0x1000U,0x100,HW_RESOURCE_MMIO,11)==0);assert(hw_resource_claim(&full,0x900000,0x100,HW_RESOURCE_MMIO,500)==0);assert(full.count==HW_RESOURCE_CAPACITY);return 0;}
